type OrderStatus = 'processing' | 'shipped' | 'delivered' | 'cancelled' | 'returned';
type Order = { id: number; status: OrderStatus; totalCents: number; customer: string };

const ORDERS: Order[] = [
  { id: 1042, status: 'shipped', totalCents: 18900, customer: 'Mona' },
  { id: 1043, status: 'processing', totalCents: 4500, customer: 'Karim' },
];

class Emitter<Events> {
  #handlers = new Map<string, Set<(payload: any) => void>>();

  on(event: string, handler: (payload: any) => void): () => void {
    let set = this.#handlers.get(event);
    if (!set) {
      set = new Set();
      this.#handlers.set(event, set);
    }
    set.add(handler);
    return () => set.delete(handler);
  }

  emit(event: string, payload?: any): void {
    for (const handler of this.#handlers.get(event) ?? []) handler(payload);
  }
}

class OrderQuery {
  readonly #fields: readonly (keyof Order)[];

  constructor(fields: readonly (keyof Order)[] = []) {
    this.#fields = fields;
  }

  select(...fields: (keyof Order)[]): OrderQuery {
    return new OrderQuery([...this.#fields, ...fields]);
  }

  run(rows: Order[]): Partial<Order>[] {
    return rows.map((row) => Object.fromEntries(this.#fields.map((f) => [f, row[f]])));
  }
}

